BEGIN;
DELETE FROM questions WHERE topic = 'Bonding & Chemical Interactions' AND subtopic IN ('Ionic Character & Bond Type', 'Resonance & Delocalization', 'Bond Length & Bond Energy');

-- Q1 [Ionic Character & Bond Type · easy · Skill 2 · general-chemistry · ans B] (g25)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Ionic Character & Bond Type',
    $qt25$A chemist compares four diatomic hydrogen halide molecules using the Pauling electronegativity values \(\text{H} = 2.1\), \(\text{F} = 4.0\), \(\text{Cl} = 3.0\), \(\text{Br} = 2.8\), and \(\text{I} = 2.5\). Assuming bond ionic character increases monotonically with the electronegativity difference between the bonded atoms, which bond is expected to have the greatest ionic character?$qt25$,
    $op25$[{"label":"A","text":"The \\(\\text{H--Br}\\) bond"},{"label":"B","text":"The \\(\\text{H--F}\\) bond"},{"label":"C","text":"The \\(\\text{H--Cl}\\) bond"},{"label":"D","text":"The \\(\\text{H--I}\\) bond"}]$op25$::jsonb,
    'B',
    $ex25$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is B because the \(\text{H--F}\) bond has the largest electronegativity difference of the four bonds, \(\left|2.1 - 4.0\right| = 1.9\), and OpenStax describes ionic character as rising continuously with \(\Delta\text{EN}\): the larger the difference, the more unequally the bonding electrons are shared and the more ionic (more polar) the bond. Ranking the differences gives \(\text{H--I} = 0.4\), \(\text{H--Br} = 0.7\), \(\text{H--Cl} = 0.9\), and \(\text{H--F} = 1.9\), so \(\text{H--F}\) sits at the top. OpenStax treats the relationship as a rough qualitative guide with many exceptions rather than a set of fixed numeric cutoffs, so only the monotonic ordering is needed here. (Choice A) The \(\text{H--Br}\) bond has \(\Delta\text{EN} = 0.7\), which is polar covalent but smaller than the \(\text{H--F}\) value, so its ionic character is not the greatest. (Choice C) The \(\text{H--Cl}\) bond has \(\Delta\text{EN} = 0.9\), the second largest difference, but it still falls short of the \(\text{H--F}\) difference and therefore has less ionic character. (Choice D) The \(\text{H--I}\) bond has the smallest difference, \(\Delta\text{EN} = 0.4\), so it is the least ionic; selecting it inverts the monotonic rule by treating the smallest \(\Delta\text{EN}\) as the most ionic. Skill 2: Scientific Reasoning and Problem-Solving.$ex25$,
    'easy', '5B', $cc25$Nature of molecules and intermolecular interactions$cc25$, 'general-chemistry', 2, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a25A$Identifies a genuinely polar bond but not the one with the maximum electronegativity difference$a25A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a25C$Selects the second-largest electronegativity difference as if it were the largest$a25C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a25D$Inverts the monotonic rule, treating the smallest electronegativity difference as the most ionic$a25D$ FROM q;

-- Q2 [Ionic Character & Bond Type · medium · Skill 2 · general-chemistry · ans C] (g26)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Ionic Character & Bond Type',
    $qt26$Using the Pauling electronegativities \(\text{H} = 2.20\), \(\text{C} = 2.55\), \(\text{O} = 3.44\), \(\text{P} = 2.19\), \(\text{Cl} = 3.16\), and \(\text{K} = 0.82\), the bonds \(\text{C}-\text{H}\), \(\text{C}-\text{O}\), \(\text{P}-\text{Cl}\), and \(\text{K}-\text{Cl}\) are ranked by increasing percent ionic character. Which ordering is correct?$qt26$,
    $op26$[{"label":"A","text":"\\(\\text{K}-\\text{Cl} < \\text{P}-\\text{Cl} < \\text{C}-\\text{O} < \\text{C}-\\text{H}\\)"},{"label":"B","text":"\\(\\text{C}-\\text{H} < \\text{P}-\\text{Cl} < \\text{C}-\\text{O} < \\text{K}-\\text{Cl}\\)"},{"label":"C","text":"\\(\\text{C}-\\text{H} < \\text{C}-\\text{O} < \\text{P}-\\text{Cl} < \\text{K}-\\text{Cl}\\)"},{"label":"D","text":"\\(\\text{K}-\\text{Cl} < \\text{C}-\\text{H} < \\text{C}-\\text{O} < \\text{P}-\\text{Cl}\\)"}]$op26$::jsonb,
    'C',
    $ex26$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is C because percent ionic character rises monotonically with the absolute electronegativity difference \(\Delta\text{EN}\), which for these bonds is \(0.35\), \(0.89\), \(0.97\), and \(2.34\) in exactly that order. Computing each difference from the given values gives \(\text{C}-\text{H} = |2.55 - 2.20| = 0.35\), \(\text{C}-\text{O} = |2.55 - 3.44| = 0.89\), \(\text{P}-\text{Cl} = |2.19 - 3.16| = 0.97\), and \(\text{K}-\text{Cl} = |0.82 - 3.16| = 2.34\); since ionic character is a monotonically increasing function of \(\Delta\text{EN}\), increasing \(\Delta\text{EN}\) is increasing ionic character, and the large \(\text{K}-\text{Cl}\) gap (above the \(\approx 1.7\) cutoff) marks it as the most ionic. The hinge is the close \(\text{C}-\text{O}\) versus \(\text{P}-\text{Cl}\) pair, which must be separated by actually subtracting \((0.89 < 0.97)\) rather than by intuition. (Choice A) This lists the bonds from most to least ionic, inverting the requested increasing order; it places the strongly ionic \(\text{K}-\text{Cl}\) (\(\Delta\text{EN} = 2.34\)) first and the nearly nonpolar \(\text{C}-\text{H}\) (\(\Delta\text{EN} = 0.35\)) last, which is the exact reverse of increasing ionic character. (Choice B) This order correctly anchors \(\text{C}-\text{H}\) lowest and \(\text{K}-\text{Cl}\) highest but transposes the middle pair, ranking \(\text{P}-\text{Cl}\) below \(\text{C}-\text{O}\); the differences \(0.97\) for \(\text{P}-\text{Cl}\) and \(0.89\) for \(\text{C}-\text{O}\) require explicit subtraction to separate, and \(\text{P}-\text{Cl}\) is in fact the larger. (Choice D) This treats a partner's small absolute electronegativity as if it lowered ionic character, demoting \(\text{K}-\text{Cl}\) to least ionic because potassium's value (\(0.82\)) is the smallest in the set; ionic character depends on the magnitude of the difference between the two atoms, not on either atom's absolute electronegativity, and the large \(\text{K}-\text{Cl}\) difference makes it the most ionic, not the least. Skill 2$ex26$,
    'medium', '5B', $cc26$Nature of molecules and intermolecular interactions$cc26$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a26A$ranks bonds from most to least ionic, inverting the requested increasing order$a26A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a26B$transposes the close middle pair (P-Cl vs C-O) by estimating instead of computing the differences$a26B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a26D$uses a partner's small absolute electronegativity rather than the EN difference, demoting K-Cl to least ionic$a26D$ FROM q;

-- Q3 [Ionic Character & Bond Type · easy · Skill 1 · general-chemistry · ans A] (g27)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Ionic Character & Bond Type',
    $qt27$Cesium and fluorine combine in \(\text{CsF}\), where the electronegativity difference \(\Delta\text{EN}\) is about 3.3. Given this very large \(\Delta\text{EN}\), how is the bonding in \(\text{CsF}\) most accurately described?$qt27$,
    $op27$[{"label":"A","text":"Essentially complete transfer of an electron from \\(\\text{Cs}\\) to \\(\\text{F}\\), giving \\(\\text{Cs}^{+}\\) and \\(\\text{F}^{-}\\)"},{"label":"B","text":"Roughly equal sharing of the bonding pair between \\(\\text{Cs}\\) and \\(\\text{F}\\)"},{"label":"C","text":"Unequal sharing of the bonding pair with partial negative charge on \\(\\text{Cs}\\)"},{"label":"D","text":"Essentially complete transfer of an electron from \\(\\text{F}\\) to \\(\\text{Cs}\\), giving \\(\\text{Cs}^{-}\\) and \\(\\text{F}^{+}\\)"}]$op27$::jsonb,
    'A',
    $ex27$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is A because a \(\Delta\text{EN}\) of about 3.3 lies far above the threshold for essentially ionic bonding, so fluorine pulls the electron away from cesium almost completely to give \(\text{Cs}^{+}\) and \(\text{F}^{-}\). As \(\Delta\text{EN}\) grows, the bonding pair shifts increasingly toward the more electronegative atom; once the difference becomes very large, the pair is no longer shared at all but is effectively held by the more electronegative atom, which constitutes ionic bonding rather than covalent sharing. Cesium is one of the least electronegative elements and fluorine is the most electronegative, so \(\text{CsF}\) represents one of the most ionic of all bonds. (Choice B) Roughly equal sharing describes a nonpolar covalent bond, which requires \(\Delta\text{EN}\) near zero, the opposite of the large value given. (Choice C) Unequal sharing describes a polar covalent bond, but it also places partial negative charge on the wrong atom; the more electronegative fluorine, not cesium, carries the negative charge. (Choice D) Complete transfer in this direction reverses the roles of the atoms, since the more electronegative fluorine gains the electron to become \(\text{F}^{-}\) while cesium loses it to become \(\text{Cs}^{+}\). Skill 1$ex27$,
    'easy', '5B', $cc27$Nature of molecules and intermolecular interactions$cc27$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
