-- Q12 [Resonance & Delocalization · easy · Skill 1 · general-chemistry · ans B] (g36)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Resonance & Delocalization',
    $qt36$A chemist compares four neutral molecules: \(\text{CH}_4\), \(\text{SO}_2\) (connectivity O-S-O), \(\text{H}_2\text{O}\), and \(\text{NH}_3\). Only one requires more than one equivalent Lewis structure to represent its bonding. Which molecule exhibits resonance?$qt36$,
    $op36$[{"label":"A","text":"\\(\\text{CH}_4\\)"},{"label":"B","text":"\\(\\text{SO}_2\\)"},{"label":"C","text":"\\(\\text{H}_2\\text{O}\\)"},{"label":"D","text":"\\(\\text{NH}_3\\)"}]$op36$::jsonb,
    'B',
    $ex36$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is B because \(\text{SO}_2\) has one \(\text{S=O}\) double bond and one \(\text{S-O}\) single bond that can be drawn in two equivalent ways, so its true structure is a resonance hybrid with the second bonding pair delocalized over both S-O positions. Because the two arrangements are equivalent, neither alone describes the molecule, and the actual S-O bonds are identical with a length and energy intermediate between a single and a double bond. (Choice A) \(\text{CH}_4\) contains only four equivalent \(\text{C-H}\) single bonds with no double bond or lone pair to relocate, so a single Lewis structure is sufficient and no resonance exists. (Choice C) \(\text{H}_2\text{O}\) has two \(\text{O-H}\) single bonds and two lone pairs on oxygen with no multiple bond to shift, so it is fully described by one Lewis structure. (Choice D) \(\text{NH}_3\) has three \(\text{N-H}\) single bonds and one lone pair on nitrogen, and with no multiple bonding to delocalize it requires only a single Lewis structure. Skill 1$ex36$,
    'easy', '5B', $cc36$Nature of molecules and intermolecular interactions$cc36$, 'general-chemistry', 1, 75
  ) RETURNING id
)
