-- Q15 [Bond Length & Bond Energy · easy · Skill 1 · general-chemistry · ans A] (g39)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Bond Length & Bond Energy',
    $qt39$Hydrogen peroxide \( \text{H}_2\text{O}_2 \) contains an oxygen-oxygen single bond, whereas molecular oxygen \( \text{O}_2 \) contains an oxygen-oxygen double bond. Which oxygen-oxygen bond is most likely the longer of the two?$qt39$,
    $op39$[{"label":"A","text":"The oxygen-oxygen single bond in \\( \\text{H}_2\\text{O}_2 \\)"},{"label":"B","text":"The oxygen-oxygen double bond in \\( \\text{O}_2 \\)"},{"label":"C","text":"Both bonds have the same length because each joins two oxygen atoms"},{"label":"D","text":"The oxygen-oxygen double bond in \\( \\text{O}_2 \\), because the second shared pair stretches the bond"}]$op39$::jsonb,
    'A',
    $ex39$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is A because the oxygen-oxygen bond in \( \text{H}_2\text{O}_2 \) is a single bond (one shared electron pair), while the bond in \( \text{O}_2 \) is a double bond (two shared electron pairs). As OpenStax describes, increasing the number of shared electron pairs between two given atoms increases the bond order and draws the nuclei closer together, so a double bond is shorter (and stronger) than a single bond between the same two atoms. Because the single bond in \( \text{H}_2\text{O}_2 \) has the lower bond order, its nuclei are held farther apart, making it the longer oxygen-oxygen bond. (Choice B) This reverses the relationship: the double bond in \( \text{O}_2 \) has the higher bond order, so its two shared pairs pull the oxygen nuclei closer and make it the shorter bond, not the longer one. (Choice C) Bond length is not fixed by atomic identity alone; for the same pair of atoms, length depends on bond order, so a single bond and a double bond between two oxygens are not equal in length. (Choice D) This contains a process error: adding a second shared electron pair raises the bond order and shortens the bond rather than stretching it, so the double bond in \( \text{O}_2 \) is shorter, not longer. Skill 1$ex39$,
    'easy', '5B', $cc39$Nature of molecules and intermolecular interactions$cc39$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a39B$Assigns the longer bond to the higher-bond-order species, inverting the bond order vs bond length relationship$a39B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a39C$Believes bond length depends only on which atoms are bonded, ignoring bond order$a39C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a39D$Correctly notes a second shared pair but reasons it lengthens rather than shortens the bond$a39D$ FROM q;

-- Q16 [Bond Length & Bond Energy · medium · Skill 2 · general-chemistry · ans B] (g40)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Bonding & Chemical Interactions', 'Bond Length & Bond Energy',
    $qt40$Hydrazine contains an \(\text{N-N}\) single bond, the diazene fragment contains an \(\text{N=N}\) double bond, and molecular nitrogen gas contains an \(\text{N}\equiv\text{N}\) triple bond. Considering only how the number of shared electron pairs between the two nitrogen atoms governs the internuclear distance, which sequence most likely orders these three nitrogen-nitrogen bonds from longest to shortest?$qt40$,
    $op40$[{"label":"A","text":"\\(\\text{N}\\equiv\\text{N} > \\text{N=N} > \\text{N-N}\\)"},{"label":"B","text":"\\(\\text{N-N} > \\text{N=N} > \\text{N}\\equiv\\text{N}\\)"},{"label":"C","text":"\\(\\text{N=N} > \\text{N}\\equiv\\text{N} > \\text{N-N}\\)"},{"label":"D","text":"\\(\\text{N-N} = \\text{N=N} = \\text{N}\\equiv\\text{N}\\), since all three join the same pair of nitrogen atoms"}]$op40$::jsonb,
    'B',
    $ex40$This is a General Chemistry question that falls under the content category 'Nature of molecules and intermolecular interactions'. The answer to this question is B because, for two bonded atoms of a given element, bond length decreases as bond order increases: each additional shared electron pair pulls the two nuclei closer together, so a single bond is longer than a double bond, which is longer than a triple bond. Between two nitrogen atoms the single bond \(\text{N-N}\) shares one pair, the double bond \(\text{N=N}\) shares two pairs, and the triple bond \(\text{N}\equiv\text{N}\) shares three pairs; the greater the number of shared pairs, the stronger the net attraction drawing the nuclei together and the shorter the internuclear distance. Ordering from longest to shortest therefore gives \(\text{N-N} > \text{N=N} > \text{N}\equiv\text{N}\), with the triple bond in \(\text{N}_2\) being the shortest of the three. (Choice A) This sequence places the triple bond as longest and the single bond as shortest, which inverts the bond-order/bond-length relationship; adding shared pairs shortens, not lengthens, the bond, so the triple bond \(\text{N}\equiv\text{N}\) is the shortest rather than the longest. (Choice C) This sequence treats the double bond as longest and misranks the triple bond above the single bond; while it correctly recognizes that bond order changes length, it does not apply the monotonic rule that length falls steadily as shared pairs increase, so the relative positions of all three are scrambled. (Choice D) Holding the two nuclei to be the same atoms does not make the bond lengths equal; bond length is set by bond order, not merely by the identity of the bonded atoms, so increasing the number of shared electron pairs progressively shortens the bond even though both atoms remain nitrogen. Skill 2$ex40$,
    'medium', '5B', $cc40$Nature of molecules and intermolecular interactions$cc40$, 'general-chemistry', 2, 110
  ) RETURNING id
)
